buildscriptGradleAdditions.insert:
dependencies
{
repositories {
// Check that you have the following line (if not, add it):
google()  // Google's Maven repository
}
classpath 'com.google.gms:google-services:4.3.3' // google-services plugin
}

buildGradleAdditions.insert:
dependencies
{
implementation 'com.google.android.play:core:1.9.0'
}

allprojects {
def mappings = [
'android.support.annotation': 'androidx.annotation',
'android.arch.lifecycle': 'androidx.lifecycle',
'android.support.v4.app.NotificationCompat': 'androidx.core.app.NotificationCompat',
'android.support.v4.app.ActivityCompat': 'androidx.core.app.ActivityCompat',
'android.support.v4.content.ContextCompat': 'androidx.core.content.ContextCompat',
'android.support.v13.app.FragmentCompat': 'androidx.legacy.app.FragmentCompat',
'android.arch.lifecycle.Lifecycle': 'androidx.lifecycle.Lifecycle',
'android.arch.lifecycle.LifecycleObserver': 'androidx.lifecycle.LifecycleObserver',
'android.arch.lifecycle.OnLifecycleEvent': 'androidx.lifecycle.OnLifecycleEvent',
'android.arch.lifecycle.ProcessLifecycleOwner': 'androidx.lifecycle.ProcessLifecycleOwner',
]

beforeEvaluate { project ->
project.rootProject.projectDir.traverse(type: groovy.io.FileType.FILES, nameFilter: ~/.*\.java$/) { f ->
mappings.each { entry ->
if (f.getText('UTF-8').contains(entry.key)) {
println "Updating ${entry.key} to ${entry.value} in file ${f}"
ant.replace(file: f, token: entry.key, value: entry.value)
}
}
}
}
}

gameActivityImportAdditions.insert:
import java.util.HashSet;
import java.util.Arrays;
import android.os.Handler;

import android.util.Log;
import android.media.AudioRecord;
import android.media.AudioFormat;
import android.media.MediaRecorder;
import android.media.AudioTrack;
import android.media.AudioManager;

import androidx.core.app.ActivityCompat;
import androidx.core.content.ContextCompat;
import android.Manifest;
import android.media.audiofx.AcousticEchoCanceler;

gameActivityClassAdditions.insert:


/* JNI UE4 Native */
private static native void orionVoiceChatDataMicPayload(short[] dataMic, int readSize);

	/* VAR */
AudioRecord microphone = null;
Thread threadMicro = null;
AudioTrack audioplayback;
RunnableVoice runableVoice;

private boolean isPermissionAllowedMic = false;

boolean use_MODE_IN_COMMUNICATION = false;

/* FUNC */

public void AndroidThunkJava_AskAndroidPermissionMicrophone(){
		ActivityCompat.requestPermissions(this, new String[]{Manifest.permission.RECORD_AUDIO}, 1);
}

public boolean AndroidThunkJava_HasAndroidPermissionMicrophone(){
		boolean res = false;
		res = ContextCompat.checkSelfPermission(this, Manifest.permission.RECORD_AUDIO) == PackageManager.PERMISSION_GRANTED;
		android.util.Log.d("OrionVoiceChat","UPL permission " + res);
		return res;
}


public boolean AndroidThunkJava_AndroidStartMicrophone(int SampleRateToUse, boolean useModeCommunication) {

		use_MODE_IN_COMMUNICATION = useModeCommunication;

		android.util.Log.d("OrionVoiceChat","UPL microphone SampleRateToUse " + SampleRateToUse +" useModeCommunication " + useModeCommunication);

		if(!isPermissionAllowedMic){
				isPermissionAllowedMic = AndroidThunkJava_HasAndroidPermissionMicrophone();
				if(!isPermissionAllowedMic) return false;
		}


		if(use_MODE_IN_COMMUNICATION){
				AudioManager mAudioManager = (AudioManager) getSystemService(Context.AUDIO_SERVICE);
				mAudioManager.setMode(AudioManager.MODE_IN_COMMUNICATION);
		}

		if(microphone == null){
				final int sampleRate = SampleRateToUse;
				final int channelConfig = AudioFormat.CHANNEL_IN_MONO;
				final int audioFormat = AudioFormat.ENCODING_PCM_16BIT;




				final int minBufferSize = AudioRecord.getMinBufferSize(sampleRate, channelConfig, audioFormat);
				microphone = new AudioRecord(MediaRecorder.AudioSource.VOICE_COMMUNICATION, sampleRate, channelConfig, audioFormat, minBufferSize );


				if(AcousticEchoCanceler.isAvailable()){
						AcousticEchoCanceler aec = AcousticEchoCanceler.create(microphone.getAudioSessionId());
						if (aec != null) {
								aec.setEnabled(true);
								android.util.Log.d("OrionVoiceChat","echo cancelation ok VOICE_COMMUNICATION");
						} else {
								android.util.Log.d("OrionVoiceChat","echo cancelation not ok VOICE_COMMUNICATION");
						}
				}
				microphone.startRecording();

				runableVoice = new RunnableVoice(minBufferSize);
				runableVoice.microphoneThread = microphone;

				threadMicro = new Thread(runableVoice);


				threadMicro.start();
		}

		microphone.startRecording();
		runableVoice.setthreadMicroRunning(true);

			return true;
}

public void AndroidThunkJava_AndroidStopMicrophone() {


		if(use_MODE_IN_COMMUNICATION){
				AudioManager mAudioManager = (AudioManager) getSystemService(Context.AUDIO_SERVICE);
				mAudioManager.setMode(AudioManager.MODE_NORMAL);
		}

		android.util.Log.d("OrionVoiceChat","UPL AndroidThunkJava_AndroidStopMicrophone setthreadMicroRunning");
		runableVoice.setthreadMicroRunning(false);
		//threadMicro.stop();
		microphone.stop();
		runableVoice.setthreadMicroRunning(false);
		//microphone.release();
}


public class RunnableVoice implements Runnable {
			public volatile boolean threadMicroRunning = false;
			public  AudioRecord microphoneThread = null;
			int minBufferSize;

			public RunnableVoice(int minBufferSize){
			this.minBufferSize = minBufferSize;
			}

			public void setthreadMicroRunning(boolean threadMicroRunning){
				this.threadMicroRunning = threadMicroRunning;
						android.util.Log.d("OrionVoiceChat","UPL setthreadMicroRunning " +  this.threadMicroRunning);
				}

		@Override
		public void run() {
			try {
				short[] buffer = new short[minBufferSize / 2];
				while (true) {
							if(threadMicroRunning){
									int readSize = microphoneThread.read(buffer, 0, buffer.length);
									android.util.Log.d("OrionVoiceChat","UPL microphone data  / 2 " + readSize +" "+buffer[0]);
									orionVoiceChatDataMicPayload(buffer, readSize);
							}
				}
			} catch(Exception e){
				e.printStackTrace();
			}
		}
}
